const data = $input.first().json.data || [];
return data.map(wf => {
  const slug = wf.name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || `workflow-${wf.id}`;
  return { json: {
    path: `workflows/${slug}.json`,
    content: JSON.stringify({ name: wf.name, nodes: wf.nodes, connections: wf.connections, settings: wf.settings }, null, 2),
    message: `backup: ${wf.name}`
  } };
});
